Lemma two_word_sub A B sh sl : wordZ A -> wordZ B -> wordZ sl -> 0 <= sh ->
  let x := W.sub B sl in
  let bo := W.b2z (W.ltu B x) in
  exists q, W.sub A (W.wrap (sh + bo)) * W.M + x = (A * W.M + B) - (sh * W.M + sl) + q * (W.M * W.M)
         /\ 0 <= W.sub A (W.wrap (sh + bo)) * W.M + x < W.M * W.M.
