  Lemma ddq2_body_exact A B q : wordZ A -> wordZ B -> d <= A * W.M + B ->
    let '(A', B', q') := ddq2_body A B q d in
    A' * W.M + B' = A * W.M + B - d /\ wordZ A' /\ wordZ B' /\ q' = W.add q 1.
Proof.
