  Lemma ddq_step2_spec A2 B2 : wordZ A2 -> wordZ B2 -> A2 * W.M + B2 < d * H ->
    let '(A4, B4, qLo) := ddq_step2 A2 B2 d in
    wordZ A4 /\ wordZ B4 /\ 0 <= qLo < H /\
    A4 * W.M + B4 = A2 * W.M + B2 - qLo * d /\ 0 <= A4 * W.M + B4 < 3 * d.
Proof.
