Lemma subm_loop_shape f : forall i carry q a b, words_ok a -> 0 <= carry <= 1 ->
  let r := subm_loop f i carry q a b in
  length (fst r) = length a /\ words_ok (fst r) /\ 0 <= snd r <= 1.
Proof.
